const body = $input.first().json.body || $input.first().json;
const lead_id = body.lead_id;
const phone = body.phone;
const message = body.message;
const phone_number_id = body.phone_number_id;
const gemini_api_key = body.gemini_api_key || '';

if (!lead_id || !message) {
  throw new Error('Missing lead_id or message');
}

return [{ json: { lead_id, phone, message, phone_number_id, gemini_api_key } }];

const lead = $('Get Lead + Brain').first().json;
const historyRows = $('Get Conversation History').all().map(i => i.json).reverse();
const userMessage = ($('Extract Data').first().json.message || '').trim();
const gemini_api_key = $('Extract Data').first().json.gemini_api_key;
const currentFlowStep = lead.current_flow_step || 'welcome';

// Build system prompt
const brandName = lead.brand_name || 'our company';
const basePrompt = lead.system_prompt || `You are a friendly WhatsApp sales assistant for ${brandName}. Qualify leads by asking about their goals, background, and budget. Guide them towards enrollment or a demo call.`;

const fullSystemPrompt = basePrompt + `

CURRENT LEAD:
- Name: ${lead.name || 'Friend'}
- Score: ${lead.score || 0}/100
- Status: ${lead.status || 'new'}
- Interest: ${lead.interest || 'Not captured yet'}
- Conversation stage: ${currentFlowStep}

RULES:
- Keep replies SHORT (max 4-5 lines)
- Be warm and conversational, not robotic
- Always end with exactly ONE question
- Reply in the SAME language the lead uses
- NEVER say you are an AI`;

// Build Gemini conversation history
const contents = [];
for (const h of historyRows) {
  contents.push({
    role: h.direction === 'inbound' ? 'user' : 'model',
    parts: [{ text: h.message || '' }]
  });
}
contents.push({ role: 'user', parts: [{ text: userMessage }] });

// Build Gemini request body as a JSON string (avoids n8n expression issues)
const geminiBody = JSON.stringify({
  system_instruction: { parts: [{ text: fullSystemPrompt }] },
  contents: contents,
  generationConfig: { maxOutputTokens: 300, temperature: 0.75, topP: 0.9 }
});

// Score lead based on message
let newScore = parseInt(lead.score) || 0;
const msgLower = userMessage.toLowerCase();
if (msgLower.match(/yes|interested|want|sure|ok|okay|tell me|know more/)) newScore = Math.min(newScore + 15, 100);
if (msgLower.match(/price|cost|fee|how much|charges/)) newScore = Math.min(newScore + 10, 100);
if (msgLower.match(/call|talk|speak|contact/)) newScore = Math.min(newScore + 20, 100);
if (msgLower.match(/pay|enroll|join|register|book|admit/)) newScore = Math.min(newScore + 30, 100);
if (msgLower.match(/not interested|no thanks|stop|wrong number/)) newScore = Math.max(newScore - 15, 0);

let newStatus = 'new';
if (newScore >= 75) newStatus = 'hot';
else if (newScore >= 40) newStatus = 'warm';
else if (newScore < 5) newStatus = 'cold';

return [{ json: {
  geminiBody,
  gemini_api_key,
  lead,
  userMessage,
  newScore,
  newStatus,
  nextFlowStep: 'free_ai',
  phone: $('Extract Data').first().json.phone,
  phone_number_id: lead.brand_phone_number_id || $('Extract Data').first().json.phone_number_id,
  wa_access_token: lead.wa_access_token
} }];

const geminiResponse = $input.first().json;
const aiText = (geminiResponse.candidates?.[0]?.content?.parts?.[0]?.text || 'Sorry, please try again.').trim();

const buildData = $('Build AI Prompt').first().json;

// Build WhatsApp message body as JSON string
const waBody = JSON.stringify({
  messaging_product: 'whatsapp',
  to: buildData.phone,
  type: 'text',
  text: { body: aiText }
});

return [{ json: {
  waBody,
  aiText,
  lead_id: buildData.lead.id,
  newScore: buildData.newScore,
  newStatus: buildData.newStatus,
  nextFlowStep: buildData.nextFlowStep,
  phone_number_id: buildData.phone_number_id,
  wa_access_token: buildData.wa_access_token
} }];
